<script setup>
import {ref,computed,onMounted,onUnmounted,nextTick,watch} from 'vue'
import {COMMON_PLATFORM} from './platforms.js'
import {prepareImage} from './question-images.js'
const user=ref(null),loading=ref(true),busy=ref(false),error=ref(''),username=ref(''),password=ref('');
const platformRecords=ref([]),platform=ref(''),question=ref(''),images=ref([]),imageBusy=ref(false),previewImage=ref(null);
const threads=ref([]),activeId=ref(''),sidebarOpen=ref(false),messageList=ref(null),fileInput=ref(null);
const platforms=computed(()=>platformRecords.value.filter(p=>p.active&&p.name!==COMMON_PLATFORM).map(p=>p.name));
const active=computed(()=>threads.value.find(t=>t.id===activeId.value));
const locked=computed(()=>busy.value||imageBusy.value);
const storageKey=()=> 'support-chats:'+user.value.username;
function persist(){if(!user.value)return;try{sessionStorage.setItem(storageKey(),JSON.stringify({activeId:activeId.value,threads:threads.value.map(t=>({...t,turns:t.turns.map(m=>({...m,images:m.images.map(i=>({name:i.name})),matches:m.matches.slice(0,20)}))}))}))}catch{}}
function newChat(){if(locked.value)return;const t={id:crypto.randomUUID(),title:'新对话',turns:[]};threads.value=[t,...threads.value].slice(0,20);activeId.value=t.id;question.value='';images.value=[];error.value='';sidebarOpen.value=false;persist();syncPlatforms()}
function restoreChats(){try{const saved=JSON.parse(sessionStorage.getItem(storageKey())||'null');if(saved&&Array.isArray(saved.threads)){threads.value=saved.threads.filter(t=>t.id&&Array.isArray(t.turns)).slice(0,20);for(const thread of threads.value)for(const turn of thread.turns)if(turn.status==='pending'){turn.status='error';turn.notice='上次请求中断，请先在待处理问题确认是否已保存。'}activeId.value=saved.activeId}}catch{}if(!active.value)newChat()}
function selectChat(id){if(locked.value)return;activeId.value=id;question.value='';images.value=[];sidebarOpen.value=false;error.value='';persist();scrollBottom()}
async function scrollBottom(){await nextTick();if(messageList.value)messageList.value.scrollTop=messageList.value.scrollHeight}
async function api(action,body){let r;try{r=await fetch('/api/support?action='+action,{method:body?'POST':'GET',cache:'no-store',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined})}catch{throw new Error('网络连接失败，请检查网络后重试')}let data;try{data=await r.json()}catch{throw new Error('服务响应异常，请稍后重试')}if(!r.ok){if(r.status===401)user.value=null;throw new Error(data.error||'服务暂不可用')}return data}
let platformSync=null;
async function load(){if(platformSync)return platformSync;platformSync=(async()=>{const dictionary=await api('platforms');if(!user.value)return;platformRecords.value=dictionary;if(!platforms.value.includes(platform.value))platform.value=''})();try{await platformSync}finally{platformSync=null}}
async function syncPlatforms(){if(!user.value||locked.value)return;try{await load()}catch(e){error.value=e.message}}
onMounted(()=>window.addEventListener('focus',syncPlatforms));
onUnmounted(()=>window.removeEventListener('focus',syncPlatforms));
async function initialize(){await load();try{const saved=JSON.parse(localStorage.getItem('support-platform')||'null');if(saved&&platforms.value.includes(saved.platform))platform.value=saved.platform}catch{}restoreChats()}
onMounted(async()=>{try{user.value=(await api('me')).user;await initialize()}catch(e){if(e.message!=='请登录')error.value=e.message}finally{loading.value=false}});
watch(platform,()=>{try{if(platform.value)localStorage.setItem('support-platform',JSON.stringify({platform:platform.value}));else localStorage.removeItem('support-platform')}catch{}});
async function login(){if(busy.value)return;busy.value=true;error.value='';try{user.value=(await api('login',{username:username.value,password:password.value})).user;password.value='';busy.value=false;await initialize()}catch(e){error.value=e.message}finally{busy.value=false}}
async function logout(){if(locked.value)return;busy.value=true;try{await api('logout',{});sessionStorage.removeItem(storageKey());user.value=null;threads.value=[];platformRecords.value=[];images.value=[];question.value='';previewImage.value=null}catch(e){error.value=e.message}finally{busy.value=false}}
function choose(turn,entry){turn.reply=entry.answer;turn.source=entry.question+' · '+(entry.source||'人工维护');persist();scrollBottom()}
async function send(){
 if(locked.value||(!question.value.trim()&&!images.value.length))return;
 if(!active.value)newChat();if(active.value.turns.length>=50){error.value='当前对话已达 50 条，请新建对话';return}
 const submitted={platform:platform.value,question:question.value.trim(),images:images.value.map(i=>({...i}))};
 const turn={id:crypto.randomUUID(),question:submitted.question,platform:submitted.platform,images:submitted.images,reply:'',source:'',matches:[],notice:'正在查询知识库…',status:'pending',imageDescription:'',editing:false};
 active.value.turns.push(turn);if(active.value.turns.length===1)active.value.title=submitted.question.slice(0,24)||'图片问题';
 const current=active.value.turns[active.value.turns.length-1];question.value='';images.value=[];busy.value=true;error.value='';scrollBottom();persist();
 try{const result=await api('answer',submitted);current.ticketId=result.ticketId;current.imageDescription=result.imageDescription||'';current.status='done';current.notice=result.notice||'问题已记录到待处理列表';
  if(result.mode==='ai'){current.reply=result.answer;current.source=result.sources.map(s=>s.question+'（'+(s.source||'人工维护')+'）').join('；');current.notice='AI 整理回复，请核对后发送'}
  else if(result.mode!=='insufficient'){current.matches=Array.isArray(result.matches)?result.matches:[];if(current.matches.length===1)choose(current,current.matches[0]);else if(current.matches.length>1)current.notice+='，请从匹配资料中选择答案';else current.notice+='。未找到匹配资料，等待管理员补充。'}
 }catch(e){current.status='error';current.notice=e.message+'。请先确认待处理问题是否已保存，再决定是否重新提交。'}finally{busy.value=false;persist();scrollBottom()}
}
async function addImages(files){if(locked.value)return;const selected=Array.from(files||[]);if(!selected.length)return;if(images.value.length+selected.length>3){error.value='每次最多上传 3 张图片';return}imageBusy.value=true;error.value='';try{const list=[];for(const f of selected)list.push(await prepareImage(f));images.value=[...images.value,...list]}catch(e){error.value=e.message}finally{imageBusy.value=false}}
async function selectImages(e){await addImages(e.target.files);e.target.value=''}
function pasteImages(e){const files=Array.from(e.clipboardData?.items||[]).filter(i=>i.kind==='file'&&i.type.startsWith('image/')).map(i=>i.getAsFile()).filter(Boolean);if(files.length){e.preventDefault();addImages(files)}}
function keyboard(e){if(e.key==='Enter'&&(e.ctrlKey||e.metaKey)&&!e.isComposing){e.preventDefault();send()}}
async function copy(turn){try{await navigator.clipboard.writeText(turn.reply);error.value='回复已复制，可粘贴到微信群'}catch{turn.editing=true;error.value='请在回复编辑框中选中文字复制'}}
</script>
<template>
<div v-if="loading" class="loading">正在连接客服工作台…</div>
<div v-else-if="!user" class="login-page"><section class="login-brand"><div class="brand">知答 <span>✦</span></div><small>培训客服工作台</small><h1>把学员的问题，<br>变成有依据的回复。</h1><p>文字提问 · 截图识别 · 平台知识</p></section><form class="login-form" @submit.prevent="login"><small>客服端</small><h2>登录客服工作台</h2><label>账号<input v-model="username" required autocomplete="username" maxlength="100"></label><label>密码<input v-model="password" type="password" required autocomplete="current-password" maxlength="256"></label><button class="primary" :disabled="busy">登录</button><p class="message" v-if="error" role="alert">{{error}}</p><p class="hint">请使用管理员分配的客服账号。</p><a href="/admin/login">管理员入口 →</a></form></div>
<div v-else class="chat-shell">
<button v-if="sidebarOpen" class="chat-scrim" aria-label="关闭会话列表" @click="sidebarOpen=false"></button>
<aside class="chat-sidebar" :class="{open:sidebarOpen}"><div class="chat-logo">知答 <span>✦</span></div><button class="chat-new" :disabled="locked" @click="newChat">＋ 新对话</button><small class="chat-list-label">当前浏览器会话</small><div class="chat-history"><button v-for="thread in threads" :key="thread.id" :class="{selected:activeId===thread.id}" :disabled="locked" @click="selectChat(thread.id)">{{thread.title}}</button></div><div class="chat-sidebar-footer"><a v-if="user.role==='admin'" href="/admin/login">管理后台 ↗</a><small>每条问题独立检索 · 自动登记反馈</small><div class="row"><span>{{user.username}}</span><button :disabled="locked" @click="logout">退出</button></div></div></aside>
<main class="chat-main"><header class="chat-topbar"><div class="row"><button class="quiet chat-menu" aria-label="打开会话列表" @click="sidebarOpen=true">☰</button><strong>培训客服助手</strong><span class="chat-tag">知识库问答</span></div><span class="chat-sync-note">每次提问自动查询最新知识</span></header>
<div class="chat-messages" ref="messageList" aria-live="polite"><div class="chat-content">
<div v-if="!active?.turns.length" class="chat-welcome"><div class="welcome-mark">✦</div><h1>今天有什么需要解答？</h1><p>粘贴学员问题或上传截图，查找可直接发送的回复。</p><div class="chat-suggestions"><button @click="question='登录时提示账号或密码错误怎么办？'">账号登录问题 ↗</button><button @click="question='人脸识别一直提示超时怎么办？'">人脸识别问题 ↗</button><button @click="question='视频播放卡顿、黑屏怎么办？'">视频学习问题 ↗</button></div></div>
<article v-for="turn in active?.turns||[]" :key="turn.id" class="chat-turn"><div class="user-message"><small>{{turn.platform||'通用知识'}}<span v-if="turn.ticketId"> · 问题 #{{turn.ticketId}}</span></small><p v-if="turn.question">{{turn.question}}</p><div v-if="turn.images.length" class="chat-image-list"><template v-for="(i,index) in turn.images" :key="index"><button v-if="i.data" @click="previewImage=i" :aria-label="'查看截图：'+i.name"><img :src="i.data" :alt="i.name"></button><small v-else>▧ {{i.name}}（原图见后台）</small></template></div></div>
<div class="assistant-message"><div class="assistant-icon">✦</div><div class="assistant-body"><div v-if="turn.status==='pending'" class="chat-thinking">{{turn.images.length?'正在识别截图并检索资料…':'正在检索知识库…'}}</div><template v-else><details v-if="turn.imageDescription" class="chat-recognition"><summary>截图识别结果 · 请核对</summary><p>{{turn.imageDescription}}</p></details><template v-if="turn.reply"><textarea v-if="turn.editing" v-model="turn.reply" rows="7" aria-label="编辑回复文案" @input="persist"></textarea><p v-else class="assistant-answer">{{turn.reply}}</p><details class="chat-source"><summary>查看答案依据</summary><p>{{turn.source}}</p></details><div class="chat-actions"><button @click="copy(turn)">复制回复</button><button @click="turn.editing=!turn.editing">{{turn.editing?'完成编辑':'编辑文案'}}</button></div></template><p :class="['chat-turn-notice',{failed:turn.status==='error'}]">{{turn.notice}}</p><div v-if="turn.matches.length>1" class="chat-matches"><button v-for="entry in turn.matches" :key="entry.id" @click="choose(turn,entry)">{{entry.question}} <span>→</span></button></div></template></div></div></article>
</div></div>
<div class="chat-composer-area"><div class="chat-composer-wrap"><div v-if="error" class="chat-toast" role="status">{{error}}<button aria-label="关闭提示" @click="error=''">×</button></div><form class="chat-composer" @submit.prevent="send"><div v-if="images.length" class="composer-images"><div v-for="(i,index) in images" :key="index"><button type="button" @click="previewImage=i" :aria-label="'预览截图：'+i.name"><img :src="i.data" :alt="i.name"></button><button type="button" class="remove-image" :disabled="locked" @click="images=images.filter((_,n)=>n!==index)" :aria-label="'删除图片 '+(index+1)">×</button></div></div><textarea v-model="question" rows="2" maxlength="2000" :disabled="locked" aria-label="学员问题" placeholder="输入学员问题，或粘贴截图…" @paste="pasteImages" @keydown="keyboard"></textarea><div class="composer-toolbar"><div class="composer-tools"><button type="button" class="attach-button" :disabled="locked" @click="fileInput.click()" aria-label="上传问题图片" title="上传图片，最多3张">＋<span>图片</span></button><input ref="fileInput" class="sr-only" type="file" accept="image/png,image/jpeg,image/webp" multiple @change="selectImages"><label class="composer-platform"><span class="sr-only">培训平台（选填）</span><select v-model="platform" :disabled="locked" @focus="syncPlatforms"><option value="">通用知识 · 平台选填</option><option v-for="p in platforms" :key="p" :value="p">{{p}}</option></select></label></div><button class="chat-send" type="submit" :disabled="locked||(!question.trim()&&!images.length)" :aria-label="busy?'正在生成':'发送问题'">{{locked?'…':'↑'}}</button></div></form><p class="composer-footnote">{{imageBusy?'正在处理图片…':'截图最多 3 张；启用 AI 时图片将发送至 OpenAI，请先遮挡个人信息。'}}<span>Ctrl / ⌘ + Enter 发送</span></p></div></div>
</main></div>
<div v-if="previewImage" class="modal image-preview" role="dialog" aria-modal="true" aria-label="问题截图预览" @click.self="previewImage=null" @keydown.esc="previewImage=null"><div class="card"><button type="button" class="quiet" @click="previewImage=null">关闭图片</button><p>{{previewImage.name}}</p><img :src="previewImage.data" :alt="previewImage.name"></div></div>
</template>
